SELECT s.Fname, s.Sex
FROM Student s
WHERE EXISTS (
    SELECT 1 FROM Has_Allergy ha
    WHERE ha.StuID = s.StuID AND ha.Allergy = 'Milk'
)
AND NOT EXISTS (
    SELECT 1 FROM Has_Allergy ha2
    WHERE ha2.StuID = s.StuID AND ha2.Allergy = 'Cat'
);

SELECT b.length_meters, a.name
FROM bridge AS b
JOIN architect AS a ON b.architect_id = a.id
WHERE b.length_meters = (
    SELECT MAX(length_meters) FROM bridge
);

SELECT SUM(p.wins + p.losses + IFNULL(p.ties, 0)) AS total_postseason_games
FROM postseason p
WHERE p.team_id_winner IN (
    SELECT DISTINCT team_id FROM team WHERE name = 'Boston Red Stockings'
)
   OR p.team_id_loser IN (
    SELECT DISTINCT team_id FROM team WHERE name = 'Boston Red Stockings'
);

SELECT `date`, ( `max_temperature_f` - `min_temperature_f` ) AS temperature_range
FROM `weather`
WHERE ( `max_temperature_f` - `min_temperature_f` ) = (
    SELECT MIN(`max_temperature_f` - `min_temperature_f`)
    FROM `weather`
);

SELECT `Address`, `Num_of_staff`
FROM `shop`
WHERE `Shop_ID` NOT IN (
    SELECT `Shop_ID` FROM `happy_hour`
);

SELECT email_address, phone_number
FROM Customers
WHERE customer_id NOT IN (
    SELECT customer_id FROM Complaints
);

SELECT DISTINCT f.Studio
FROM film f
WHERE f.Studio NOT IN (
    SELECT Studio FROM film WHERE Director = 'Walter Hill'
);

SELECT `Company`, `Main_Industry`
FROM `company`
WHERE `Company_ID` NOT IN (
    SELECT `Company_ID` FROM `station_company`
);

SELECT `Name`
FROM `technician`
WHERE `technician_id` NOT IN (
    SELECT `technician_id` FROM `repair_assignment`
);

SELECT DISTINCT r.name
FROM Reviewer r
WHERE EXISTS (
    SELECT 1 FROM Rating rt3
    WHERE rt3.rID = r.rID AND rt3.stars = 3
) AND EXISTS (
    SELECT 1 FROM Rating rt4
    WHERE rt4.rID = r.rID AND rt4.stars = 4
);

SELECT billing_state, COUNT(*) AS invoice_count
FROM invoices
GROUP BY billing_state
HAVING COUNT(*) = (
    SELECT MAX(cnt) FROM (
        SELECT COUNT(*) AS cnt
        FROM invoices
        GROUP BY billing_state
    ) AS sub
);

SELECT SUM(`Number_Deaths`) AS total_deaths, SUM(`Damage_millions_USD`) AS total_damage_millions
FROM `storm`
WHERE `Max_speed` > (
    SELECT AVG(`Max_speed`) FROM `storm`
);
